+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+const sessionWith = (content: string): ChatSession => ({
+  sessionId: 's1',
+  userId: 'u1',
+  entries: [{role: 'user', content, timestamp: SENT_AT}],
+});
+
+const throwingProvider = (thrown: unknown): AIProvider => ({
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    yield* [] as MessageChunk[];
+    throw thrown;
+  },
+  async generateStructured<T>(): Promise<T> {
+    return {} as T;
+  },
+});
+
+const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
+
+const runFailingTurn = async (thrown: unknown) => {
+  const seen: Error[] = [];
+  const hooks: OrchestratorHooks = {
+    onError: async (_session, error) => {
+      seen.push(error);
+    },
+  };
+  const orchestrator = createChatOrchestrator(throwingProvider(thrown), promptBuilder, undefined, {hooks});
+  const rejected = await orchestrator.processMessage(sessionWith('hello')).then(
+    () => undefined,
+    (reason: unknown) => reason
+  );
+  return {seen, rejected};
+};
+
+describe('ChatOrchestrator onError for non-Error rejections', () => {
+  it('calls onError with an Error normalized from a non-Error rejection while passing an Error instance unchanged', async () => {
+    const stringTurn = await runFailingTurn('provider rejected with a string');
+    const originalError = new Error('real error instance');
+    const errorTurn = await runFailingTurn(originalError);
+
+    expect({
+      stringCalled: stringTurn.seen.length,
+      stringIsError: stringTurn.seen[0] instanceof Error,
+      stringMessage: stringTurn.seen[0]?.message,
+      stringRejected: stringTurn.rejected,
+      errorSameInstance: errorTurn.seen[0] === originalError,
+    }).toEqual({
+      stringCalled: 1,
+      stringIsError: true,
+      stringMessage: 'provider rejected with a string',
+      stringRejected: 'provider rejected with a string',
+      errorSameInstance: true,
+    });
+  });
+});

